function inverterPares() {
  const cards = document.querySelectorAll('.card-horizontal');
  cards.forEach((card, i) => {
    if ((i + 1) % 2 === 0) {
      card.style.flexDirection = 'row-reverse';
    }
  });
}

// Roda após o DOM estar pronto
document.addEventListener('DOMContentLoaded', () => {
  inverterPares();

  // Se o repeater carrega depois via AJAX, tenta observar mudanças no body e reaplicar
  const observer = new MutationObserver(() => {
    inverterPares();
  });

  observer.observe(document.body, { childList: true, subtree: true });
});





